import http_range
from starlette.datastructures import parse_range_header

async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
    if self.stat_result is None:
        try:
            stat_result = await anyio.to_thread.run_sync(os.stat, self.path)
            self.set_stat_headers(stat_result)
        except FileNotFoundError:
            raise RuntimeError(f"File at path {self.path} does not exist.")
        else:
            mode = stat_result.st_mode
            if not stat.S_ISREG(mode):
                raise RuntimeError(f"File at path {self.path} is not a file.")
    await send(
        {
            "type": "http.response.start",
            "status": self.status_code,
            "headers": self.raw_headers,
        }
    )
    if scope["method"].upper() == "HEAD":
        await send({"type": "http.response.body", "body": b"", "more_body": False})
    else:
        range_header = scope.get('headers', {}).get(b'range')
        if range_header:
            ranges = parse_range_header(range_header.decode())
            for start, end in ranges:
                if start >= self.stat_result.st_size or end > self.stat_result.st_size:
                    continue
                if end is None:
                    end = self.stat_result.st_size - 1
                content_length = end - start + 1
                content_range = f"bytes {start}-{end}/{self.stat_result.st_size}"
                self.headers.setdefault("content-range", content_range)
                self.headers.setdefault("accept-ranges", "bytes")
                await send(
                    {
                        "type": "http.response.start",
                        "status": 206,
                        "headers": self.raw_headers,
                    }
                )
                async with await anyio.open_file(self.path, mode="rb") as file:
                    file.seek(start)
                    more_body = True
                    while more_body:
                        chunk = await file.read(min(content_length, self.chunk_size))
                        more_body = len(chunk) == self.chunk_size
                        await send(
                            {
                                "type": "http.response.body",
                                "body": chunk,
                                "more_body": more_body,
                            }
                        )
                        content_length -= len(chunk)
        else:
            async with await anyio.open_file(self.path, mode="rb") as file:
                more_body = True
                while more_body:
                    chunk = await file.read(self.chunk_size)
                    more_body = len(chunk) == self.chunk_size
                    await send(
                        {
                            "type": "http.response.body",
                            "body": chunk,
                            "more_body": more_body,
                        }
                    )
    if self.background is not None:
        await self.background()
